/* Topic-first, manually selected course references and existing licensed collections. */
let aSkills=null,aCollection=null,aCollectionPage=0,aExtraLoaded=false;
async function aExtraCourses(){if(aExtraLoaded)return;const rows=await aFetch('./data/skill_courses.json');for(const c of rows)if(!courses.some(x=>x.id===c.id))courses.push(c);aExtraLoaded=true}
async function aLoadSkills(){await aExtraCourses();if(!aSkills)aSkills=await aFetch('./data/skill_catalog.json');return aSkills}
const aResolveBeforeSkills=aResolve;aResolve=async function(){const hash=location.hash,route=academyRoute(hash);aRoute=route;aError=false;aLoading=true;render();try{if(['path','step'].includes(route.kind)&&['cours-cv-candidatures','cours-entretien-professionnel','cours-documents-pratique','cours-tableurs-pratique'].includes(route.id))await aExtraCourses();if(['bibliotheque','collection'].includes(route.kind)){await aLoadSkills();aCollectionPage=0;if(route.kind==='collection')aCollection=await aFetch('./data/collections/'+encodeURIComponent(route.id)+'.json')}}catch{if(location.hash===hash){aLoading=false;aError=true;render()}return}if(location.hash!==hash)return;return aResolveBeforeSkills()};
const aLibraryBeforeSkills=aLibrary;aLibrary=function(){if(aRoute.id==='competences')return aSkillHub();if(aRoute.id==='theme')return aSkillTopic(aRoute.careerId);const html=aLibraryBeforeSkills();if(!aSkills||aQuery.trim()||aFormat!=='all'||aSubject!=='all')return html;return html.replace('<section class="a-library-search">',`<section class="a-skills-invite"><div><span class="eyebrow">${esc(at('skillsExplorer'))}</span><h2>${esc(at('chooseSkill'))}</h2><p>${esc(at('skillsNote'))}</p></div>${aLink('#/bibliotheque/competences','exploreSkills','primary')}</section><section class="a-library-search">`)};
const aViewBeforeSkills=aView;aView=function(){if(aRoute.kind==='collection')return aCollectionView();return aViewBeforeSkills()};
function aSkillHub(){if(!aSkills)return `<p>${esc(at('load'))}</p>`;return aPageHead('skillsExplorer',at('skillsNote'))+`<div class="a-skill-grid">${aSkills.topics.map(t=>`<a class="a-skill-topic" href="#/bibliotheque/theme/${t.id}">${icon(t.icon)}<h2>${esc(t.title_fr)}</h2><span>${esc(at('showCourses'))} →</span></a>`).join('')}</div><details class="panel"><summary>${esc(at('providers'))}</summary><p>LearnFree · Khan Academy · Microsoft Learn · freeCodeCamp · OpenLearn</p><p>${esc(at('sourceCourseNote'))}</p><a href="https://www.classcentral.com/report/big-tech-free-courses/" target="_blank" rel="noopener">Class Central · ${esc(at('discoveryOnly'))} ↗</a></details>`}
function aSkillTopic(id){const t=aSkills?.topics.find(t=>t.id===id);if(!t)return aPageHead('unknown');const external=aSkills.courses.filter(c=>c.topic===id),own=t.course_ids.map(id=>getCourse(id)).filter(Boolean);return aLink('#/bibliotheque/competences','back','back-link')+`<header class="a-page-head"><span class="eyebrow">${esc(at('skillsExplorer'))}</span><h1>${esc(t.title_fr)}</h1><p>${esc(at('sourceCourseNote'))}</p></header><section class="a-section"><h2>${esc(at('learnHere'))}</h2><div class="a-library-shelf">${own.map(c=>`<a href="#/parcours/cours-${c.id}" class="a-shelf-card"><span class="eyebrow">NUNYA · FR · ${c.duration} min</span><h3>${esc(c.title)}</h3><p>${esc(at('textOnly'))} · ${esc(at('free'))}</p><span>${esc(at('start'))} →</span></a>`).join('')}</div></section><section class="a-section"><h2>${esc(at('courseCollections'))}</h2><div class="a-collection-grid">${external.slice(aCollectionPage*9,aCollectionPage*9+9).map(aCollectionCard).join('')}</div>${external.length>9?`<div class="a-inline-actions"><button class="secondary" data-collection-page="prev" ${aCollectionPage===0?'disabled':''}>${esc(at('previous'))}</button><span>${aCollectionPage+1}/${Math.ceil(external.length/9)}</span><button class="secondary" data-collection-page="next" ${(aCollectionPage+1)*9>=external.length?'disabled':''}>${esc(at('following'))}</button></div>`:''}</section>`}
function aCollectionCard(c){return `<a class="a-collection-card" href="#/collection/${c.id}"><div class="a-collection-art">${icon(c.provider==='Khan Academy'?'book':c.provider==='LearnFree'?'monitor':'compass')}<span>${esc(c.provider)}</span></div><div><span class="eyebrow">${esc(c.integration==='embedded'?'FR · '+c.resource_count+' '+at('step'):at('frenchCompanion'))}</span><h3>${esc(c.title_fr)}</h3><p>${esc(c.description_fr)}</p><small>${esc(at('free'))} · ${esc(c.language.includes('fr')?'Source FR':'Source EN · guide FR')}</small><span>${esc(at('openCollection'))} →</span></div></a>`}
function aCollectionView(){if(!aCollection)return `<p>${esc(at('load'))}</p>`;const c=aCollection.course,guide=c.guide_course_id&&getCourse(c.guide_course_id),rows=aCollection.resources;return aLink('#/bibliotheque/theme/'+c.topic,'back','back-link')+`<header class="a-path-hero"><span class="eyebrow">${esc(c.provider)} · ${esc(at('free'))}</span><h1>${esc(c.title_fr)}</h1><p>${esc(c.description_fr)}</p><small>${esc(c.language.includes('fr')?'Source FR':'Source EN · accompagnement Nunya FR')} · ${esc(at('sourceChecked'))} ${esc(c.last_checked)}</small>${guide?`<div class="a-hero-actions">${aLink('#/parcours/cours-'+guide.id,'startFrench','primary')}</div>`:''}</header>${c.video?`<section class="a-collection-video panel"><h2>${esc(at('optionalVideo'))} · ${c.video.language==='fr'?'FR':'EN'}</h2><p>${esc(at('videoLanguageNote'))}</p><div class="study-video" id="a-collection-player"><button class="study-play" data-collection-video="${c.video.id}" aria-label="${esc(at('optionalVideo'))}"><span aria-hidden="true">▷</span><strong>${esc(at('playHere'))}</strong><small>${esc(c.video.provider)}</small></button></div></section>`:''}${guide?`<section class="panel"><h2>${esc(at('frenchCompanion'))}</h2><p>${esc(at('companionHonesty'))}</p><ol class="a-step-list">${guide.lessons.map((l,i)=>`<li><a href="#/parcours/cours-${guide.id}/etape/${i}"><span>${i+1}</span><span>${esc(l.title)}<small>${esc(at('read'))} · ${esc(at('walk'))} · ${esc(at('practice'))}</small></span><span>→</span></a></li>`).join('')}</ol></section>`:`<section class="a-section"><h2>${esc(at('showSteps'))}</h2><div class="resource-grid">${rows.slice(aCollectionPage*9,aCollectionPage*9+9).map(resourceCard).join('')}</div><div class="a-inline-actions"><button class="secondary" data-collection-page="prev" ${aCollectionPage===0?'disabled':''}>${esc(at('previous'))}</button><span>${aCollectionPage+1}/${Math.max(1,Math.ceil(rows.length/9))}</span><button class="secondary" data-collection-page="next" ${(aCollectionPage+1)*9>=rows.length?'disabled':''}>${esc(at('following'))}</button></div></section>`}<details class="panel"><summary>${esc(at('sources'))}</summary><p>${esc(c.attribution)}</p><p>${esc(c.license)}</p><p>${esc(at('sourceCourseNote'))}</p><a href="${esc(c.url)}" target="_blank" rel="noopener">${esc(at('official'))}</a>${c.terms_url?` · <a href="${esc(c.terms_url)}" target="_blank" rel="noopener">${esc(at('terms'))}</a>`:''}</details>`}
document.addEventListener('click',e=>{const b=e.target.closest('[data-collection-page],[data-collection-video],[data-search-page]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();if(b.dataset.searchPage){aSearchPage=Math.max(0,aSearchPage+(b.dataset.searchPage==='next'?1:-1));render();$('#main').scrollIntoView({block:'start'});return}if(b.dataset.collectionPage){aCollectionPage=Math.max(0,aCollectionPage+(b.dataset.collectionPage==='next'?1:-1));render();$('#main').scrollIntoView({block:'start'});return}if(b.dataset.collectionVideo&&/^[\w-]{11}$/.test(b.dataset.collectionVideo))$('#a-collection-player').innerHTML=`<iframe src="https://www.youtube-nocookie.com/embed/${b.dataset.collectionVideo}?rel=0&hl=fr&playsinline=1" title="${esc(aCollection.course.title_fr)}" allow="encrypted-media; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>`},true);
